function [reconstructedImage, metrics] = decompressImage(compressedPath)

    % ============================================================
    % STANDARD DCT IMAGE DECOMPRESSION
    %
    % Reconstructs the image from the 5-D coefficient structure
    % generated by actualCompression.m
    %
    % Image blocks are always 8x8.
    % Retained frequency region may be smaller, e.g. 6x6.
    %
    % Toolbox-independent implementation
    % ============================================================

    % ------------------------------------------------------------
    % LOAD COMPRESSED DATA
    % ------------------------------------------------------------

    data = load(compressedPath);

    retainedCoefficients = data.retainedCoefficients;

    compressedRows = data.compressedRows;
    compressedCols = data.compressedCols;

    channels = data.channels;

    quantMatrix = data.quantMatrix;

    quality = data.quality;

    % ------------------------------------------------------------
    % IMAGE BLOCK SIZE
    % ------------------------------------------------------------

    imageBlockSize = 8;

    % ------------------------------------------------------------
    % DETERMINE RETAINED FREQUENCY SIZE
    %
    % retainedCoefficients dimensions are:
    %
    % [retainedRows, retainedCols,
    %  blockRow, blockCol, channel]
    %
    % Example at quality 50:
    %
    % 6 x 6 x 48 x 64 x 3
    %
    % Therefore retained frequency size = 6.
    % ------------------------------------------------------------

    coefficientDimensions = ...
        size(retainedCoefficients);

    retainedFrequencySize = ...
        coefficientDimensions(1);

    % ------------------------------------------------------------
    % NUMBER OF IMAGE BLOCKS
    % ------------------------------------------------------------

    numRowsBlocks = ...
        compressedRows / imageBlockSize;

    numColsBlocks = ...
        compressedCols / imageBlockSize;

    % ------------------------------------------------------------
    % CREATE 8x8 DCT MATRIX
    % ------------------------------------------------------------

    N = 8;

    D = zeros(N,N);

    for k = 0:N-1

        for n = 0:N-1

            if k == 0
                alpha = sqrt(1/N);
            else
                alpha = sqrt(2/N);
            end

            D(k+1,n+1) = ...
                alpha * cos( ...
                (pi * (2*n + 1) * k) / (2*N));

        end

    end

    % ------------------------------------------------------------
    % INITIALIZE RECONSTRUCTED IMAGE
    % ------------------------------------------------------------

    reconstructedImage = zeros( ...
        compressedRows, ...
        compressedCols, ...
        channels);

    % ------------------------------------------------------------
    % DECOMPRESS EACH COLOR CHANNEL
    % ------------------------------------------------------------

    for channel = 1:channels

        for blockRow = 1:numRowsBlocks

            for blockCol = 1:numColsBlocks

                % ------------------------------------------------
                % CREATE FULL 8x8 DCT BLOCK
                % ------------------------------------------------

                quantizedBlock = zeros(8,8);

                % ------------------------------------------------
                % GET RETAINED FREQUENCY COEFFICIENTS
                %
                % Only the top-left NxN coefficients were stored.
                % ------------------------------------------------

                selectedCoefficients = ...
                    double( ...
                    retainedCoefficients( ...
                    :, :, ...
                    blockRow, ...
                    blockCol, ...
                    channel));

                % ------------------------------------------------
                % PLACE RETAINED COEFFICIENTS INTO 8x8 BLOCK
                % ------------------------------------------------

                quantizedBlock( ...
                    1:retainedFrequencySize, ...
                    1:retainedFrequencySize) = ...
                    selectedCoefficients;

                % ------------------------------------------------
                % DEQUANTIZATION
                % ------------------------------------------------

                dctBlock = ...
                    quantizedBlock .* quantMatrix;

                % ------------------------------------------------
                % INVERSE DCT
                % ------------------------------------------------

                reconstructedBlock = ...
                    D' * dctBlock * D;

                % ------------------------------------------------
                % ADD BACK LEVEL SHIFT
                % ------------------------------------------------

                reconstructedBlock = ...
                    reconstructedBlock + 128;

                % ------------------------------------------------
                % IMAGE POSITION
                %
                % IMPORTANT:
                % Image blocks are ALWAYS 8x8.
                % ------------------------------------------------

                rowStart = ...
                    (blockRow - 1) * imageBlockSize + 1;

                colStart = ...
                    (blockCol - 1) * imageBlockSize + 1;

                % ------------------------------------------------
                % STORE FULL 8x8 BLOCK
                % ------------------------------------------------

                reconstructedImage( ...
                    rowStart:rowStart+imageBlockSize-1, ...
                    colStart:colStart+imageBlockSize-1, ...
                    channel) = ...
                    reconstructedBlock;

            end

        end

    end

    % ------------------------------------------------------------
    % CLIP PIXEL VALUES
    % ------------------------------------------------------------

    reconstructedImage = uint8( ...
        max(0, min(255, reconstructedImage)));

    % ------------------------------------------------------------
    % FIND PROJECT ROOT
    % ------------------------------------------------------------

    compressedFullPath = ...
        fullfile(compressedPath);

    compressedFolder = ...
        fileparts(compressedFullPath);

    [parentFolder, folderName] = ...
        fileparts(compressedFolder);

    if strcmpi(folderName, 'multi_quality')

        % multi_quality -> results -> project root

        projectRoot = ...
            fileparts(parentFolder);

    else

        % results -> project root

        projectRoot = ...
            fileparts(compressedFolder);

    end

    % ------------------------------------------------------------
    % FIND ORIGINAL IMAGE
    % ------------------------------------------------------------

    originalPath = ...
        fullfile( ...
        projectRoot, ...
        'test_images', ...
        'peppers.png');

    % ------------------------------------------------------------
    % CALCULATE QUALITY METRICS
    % ------------------------------------------------------------

    if isfile(originalPath)

        originalImage = ...
            imread(originalPath);

        % Crop original to compressed dimensions

        originalImage = ...
            originalImage( ...
            1:compressedRows, ...
            1:compressedCols, :);

        originalDouble = ...
            double(originalImage);

        reconstructedDouble = ...
            double(reconstructedImage);

        % --------------------------------------------------------
        % MSE
        % --------------------------------------------------------

        difference = ...
            reconstructedDouble - originalDouble;

        metrics.MSE = ...
            mean(difference(:).^2);

        % --------------------------------------------------------
        % PSNR
        % --------------------------------------------------------

        if metrics.MSE == 0

            metrics.PSNR = Inf;

        else

            metrics.PSNR = ...
                10 * log10( ...
                (255^2) / metrics.MSE);

        end

        % --------------------------------------------------------
        % CORRELATION-BASED SIMILARITY
        %
        % NOTE:
        % This is correlation-based similarity.
        % It is NOT formal SSIM.
        %
        % We will replace this with true SSIM later.
        % --------------------------------------------------------

        originalVector = ...
            originalDouble(:);

        reconstructedVector = ...
            reconstructedDouble(:);

        correlationMatrix = ...
            corrcoef( ...
            originalVector, ...
            reconstructedVector);

        if size(correlationMatrix,1) == 2

            metrics.Similarity = ...
                correlationMatrix(1,2);

        else

            metrics.Similarity = 1;

        end

    else

        metrics.MSE = NaN;

        metrics.PSNR = NaN;

        metrics.Similarity = NaN;

        fprintf('\n');
        fprintf('WARNING: Original image not found.\n');
        fprintf('Expected location:\n');
        fprintf('%s\n', originalPath);

    end

    % ------------------------------------------------------------
    % COMPRESSED FILE SIZE
    % ------------------------------------------------------------

    compressedInfo = ...
        dir(compressedPath);

    if ~isempty(compressedInfo)

        metrics.CompressedFileSizeKB = ...
            compressedInfo.bytes / 1024;

    else

        metrics.CompressedFileSizeKB = NaN;

    end

    % ------------------------------------------------------------
    % STORE METADATA
    % ------------------------------------------------------------

    metrics.ImageHeight = ...
        compressedRows;

    metrics.ImageWidth = ...
        compressedCols;

    metrics.ColorChannels = ...
        channels;

    metrics.BlockSize = ...
        imageBlockSize;

    metrics.RetainedFrequencySize = ...
        retainedFrequencySize;

    metrics.Quality = ...
        quality;

    % ------------------------------------------------------------
    % DISPLAY RESULTS
    % ------------------------------------------------------------

    fprintf('\n');
    fprintf('============================================================\n');
    fprintf('             DCT DECOMPRESSION RESULTS\n');
    fprintf('============================================================\n');

    fprintf( ...
        'Image Height            : %d pixels\n', ...
        compressedRows);

    fprintf( ...
        'Image Width             : %d pixels\n', ...
        compressedCols);

    fprintf( ...
        'Color Channels          : %d\n', ...
        channels);

    fprintf( ...
        'Retained Frequency Size : %d x %d\n', ...
        retainedFrequencySize, ...
        retainedFrequencySize);

    fprintf( ...
        'Compressed File Size    : %.2f KB\n', ...
        metrics.CompressedFileSizeKB);

    fprintf('\n');

    fprintf( ...
        'MSE                     : %.4f\n', ...
        metrics.MSE);

    fprintf( ...
        'PSNR                    : %.2f dB\n', ...
        metrics.PSNR);

    fprintf( ...
        'Similarity              : %.4f\n', ...
        metrics.Similarity);

    fprintf('============================================================\n');

end